const upsertCareRuleCursor = `-- name: UpsertCareRuleCursor :one

INSERT INTO care_rule_cursors (plan_id, workspace_id, rule_key, last_resolved_ordinal, decision, anchor_date, next_due_date, updated_at)
VALUES ($1, $2, $3, $4, $5, $6, $7, now())
ON CONFLICT (plan_id, rule_key) DO UPDATE SET
  last_resolved_ordinal = EXCLUDED.last_resolved_ordinal,
  decision = EXCLUDED.decision,
  anchor_date = EXCLUDED.anchor_date,
  next_due_date = EXCLUDED.next_due_date,
  updated_at = now()
RETURNING plan_id, workspace_id, rule_key, last_resolved_ordinal, decision, anchor_date, next_due_date, updated_at
`

type UpsertCareRuleCursorParams struct {
	PlanID              pgtype.UUID
	WorkspaceID         pgtype.UUID
	RuleKey             string
	LastResolvedOrdinal pgtype.Int8
	Decision            NullOccurrenceStatus
	AnchorDate          pgtype.Date
	NextDueDate         pgtype.Date
}

// T02.care canonical queries. Source/profile CRUD arrives with T21; the
// engine-side materialization and resolution flows land with T22/T23 and will
// extend this file. Kept minimal on purpose: cursor state, agenda paging and
// plan/occurrence reads are the shared primitives.
func (q *Queries) UpsertCareRuleCursor(ctx context.Context, arg UpsertCareRuleCursorParams) (CareRuleCursor, error) {
	row := q.db.QueryRow(ctx, upsertCareRuleCursor,
		arg.PlanID,
		arg.WorkspaceID,
		arg.RuleKey,
		arg.LastResolvedOrdinal,
		arg.Decision,
		arg.AnchorDate,
		arg.NextDueDate,
	)
	var i CareRuleCursor
	err := row.Scan(
		&i.PlanID,
		&i.WorkspaceID,
		&i.RuleKey,
		&i.LastResolvedOrdinal,
		&i.Decision,
		&i.AnchorDate,
		&i.NextDueDate,
		&i.UpdatedAt,
	)
	return i, err
}

const upsertDigestIntent = `-- name: UpsertDigestIntent :exec
INSERT INTO notifications (id, workspace_id, owner_id, channel, dedup_key,
  ref_kind, ref_id, title, body, digest_date, scheduled_at, message_id)
VALUES ($1, $2, $3, 'EMAIL', $4, 'OCCURRENCE', $5, $6, $7, $8, $9, $10)
ON CONFLICT (workspace_id, dedup_key) DO UPDATE SET
  title = EXCLUDED.title,
  body = EXCLUDED.body,
  ref_id = EXCLUDED.ref_id,
  scheduled_at = EXCLUDED.scheduled_at,
  message_id = EXCLUDED.message_id
`

type UpsertDigestIntentParams struct {
	ID          pgtype.UUID
	WorkspaceID pgtype.UUID
	OwnerID     pgtype.UUID
	DedupKey    string
	RefID       pgtype.UUID
	Title       string
	Body        string
	DigestDate  pgtype.Date
	ScheduledAt pgtype.Timestamptz
	MessageID   pgtype.Text
}

// One digest per owner per local date (dedup key); the row refreshes in
// place until delivered so late-appearing tasks ride the same digest —
// never a second digest for the same day.
func (q *Queries) UpsertDigestIntent(ctx context.Context, arg UpsertDigestIntentParams) error {
	_, err := q.db.Exec(ctx, upsertDigestIntent,
		arg.ID,
		arg.WorkspaceID,
		arg.OwnerID,
		arg.DedupKey,
		arg.RefID,
		arg.Title,
		arg.Body,
		arg.DigestDate,
		arg.ScheduledAt,
		arg.MessageID,
	)
	return err
}
